// Parent passes the same props -> no re-render
// Parent passes new props -> re-render

import { useMemo, useState } from 'react';

interface Product {
  id: number;
  name: string;
  price: number;
}

function ProductList({ products, filter }: { products: Product[]; filter: string }) {
  const [count, setCount] = useState(0);

  const visibleProducts = useMemo(() => {
    console.log('Filtering products...');
    return products.filter(p =>
      p.name.toLowerCase().includes(filter.toLowerCase())
    );
  }, [products, filter]);

  return (
    <div>
      <button onClick={() => setCount(c => c + 1)}>
        Count: {count}
      </button>
      <ul>
        {visibleProducts.map(p => (
          <li key={p.id}>{p.name} - ${p.price}</li>
        ))}
      </ul>
    </div>
  );
}

import { useCallback, useState } from 'react';

const ItemList = React.memo(({ items, onRemove }: any) => {
  console.log('Rendering ItemList');
  return items.map(item => (
    <li key={item.id}>
      {item.name}
      <button onClick={() => onRemove(item.id)}>Remove</button>
    </li>
  ));
});

function Parent() {
  const [items, setItems] = useState([
    { id: 1, name: 'First' },
    { id: 2, name: 'Second' }
  ]);
  const [count, setCount] = useState(0);

  const handleRemove = useCallback((id: number) => {
    setItems(prev => prev.filter(item => item.id !== id));
  }, []);

  return (
    <div>
      <button onClick={() => setCount(c => c + 1)}>Count: {count}</button>
      <ItemList items={items} onRemove={handleRemove} />
    </div>
  );
}

